(function(){if(document.getElementById("orbit-badge"))return;const style=document.createElement("style");style.textContent=`#orbit-badge{position:fixed;bottom:20px;right:20px;z-index:999999;font-family:Arial,sans-serif;color:#3d3d3d}#orbit-badge button{font:inherit;cursor:pointer;border:none}#orbit-badge-trigger{display:flex;align-items:center;gap:9px;padding:11px 17px;border-radius:30px;background:#f27a97;color:#fff;font-size:14px;font-weight:700;box-shadow:0 4px 20px rgba(224,90,122,.3);transition:transform .2s,background .2s}#orbit-badge-trigger:hover{background:#e05a7a;transform:translateY(-2px)}#orbit-badge-popup{position:absolute;bottom:55px;right:0;width:245px;padding:17px;border-radius:15px;background:#fcd9e2;box-shadow:0 8px 35px rgba(224,90,122,.15);opacity:0;visibility:hidden;transform:translateY(10px);transition:.2s ease;border:1px solid #f7b3c6}#orbit-badge-popup.open{opacity:1;visibility:visible;transform:translateY(0)}#orbit-badge-popup h3{margin:0 0 8px;font-size:18px;font-weight:800;color:#e05a7a;line-height:1.3}#orbit-badge-popup p{margin:0 0 15px;color:#555;font-size:13.5px;font-weight:600;line-height:1.5}#orbit-badge-links{display:flex;gap:8px;margin-top:4px}#orbit-badge-popup a{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;flex:1;padding:13px 6px;border-radius:9px;background:#f7b3c6;color:#3d3d3d;text-decoration:none;font-size:12.5px;font-weight:700;transition:background .2s,color .2s}#orbit-badge-popup a:hover{background:#f4a3ba;color:#fff}#orbit-badge-popup a svg{width:20px;height:20px;fill:currentColor;flex-shrink:0}#orbit-badge-popup .footer{margin-top:15px;color:#f27a97;font-size:11px;text-align:center;font-weight:800;letter-spacing:.3px}`;document.head.appendChild(style);const badge=document.createElement("div");badge.id="orbit-badge";badge.innerHTML=`<div id="orbit-badge-popup"><h3>Need a website like this?</h3><p>Contact me the way that suits you best!</p><div id="orbit-badge-links"><a href="https://justorbit.pages.dev" target="_blank"><svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M4 4h16a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1h-6v2h3v2H7v-2h3v-2H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1Zm1 2v9h14V6H5Z"/></svg><span>Portfolio</span></a><a href="https://instagram.com/justorbit.dev" target="_blank"><svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M7.8 2h8.4A5.8 5.8 0 0 1 22 7.8v8.4A5.8 5.8 0 0 1 16.2 22H7.8A5.8 5.8 0 0 1 2 16.2V7.8A5.8 5.8 0 0 1 7.8 2Zm0 2A3.8 3.8 0 0 0 4 7.8v8.4A3.8 3.8 0 0 0 7.8 20h8.4a3.8 3.8 0 0 0 3.8-3.8V7.8A3.8 3.8 0 0 0 16.2 4H7.8ZM12 7a5 5 0 1 1 0 10 5 5 0 0 1 0-10Zm0 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6Zm5.5-3.3a1.2 1.2 0 1 1 0 2.4 1.2 1.2 0 0 1 0-2.4Z"/></svg><span>Instagram</span></a><a href="mailto:justorbit@aster.cx"><svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M3 5h18a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1Zm1.4 2L12 12.4 19.6 7H4.4ZM4 17h16V9.2l-7.5 5.3a1 1 0 0 1-1 0L4 9.2V17Z"/></svg><span>Email</span></a></div><div class="footer">Crafted by Orbit</div></div><button id="orbit-badge-trigger"><span><svg xmlns="http://www.w3.org/2000/svg" width="1.5em" height="1.5em" viewBox="0 0 24 24"><path d="M0 0h24v24H0z" fill="none"/><path fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5.376 14.826c-1.995 2.8-2.882 5.087-2.085 5.883c.796.797 3.083-.09 5.884-2.085c1.59-1.132 3.344-2.621 5.086-4.363s3.231-3.497 4.363-5.086c1.995-2.8 2.882-5.088 2.085-5.884c-.796-.797-3.083.09-5.883 2.085m3.798 3.799a7.2 7.2 0 0 1-9.45 9.45m7.917-11.716A7.2 7.2 0 1 0 6.91 17.09"/></svg></span> Made by Orbit</button>`;document.body.appendChild(badge);const trigger=badge.querySelector("#orbit-badge-trigger");const popup=badge.querySelector("#orbit-badge-popup");trigger.addEventListener("click",function(){popup.classList.toggle("open")});document.addEventListener("click",function(event){if(!badge.contains(event.target)){popup.classList.remove("open")}})})();
